// GOOD: Safe API usage with parameterized queries and basic input validation
import javax.servlet.http.*;
import java.io.IOException;
import java.io.PrintWriter;
import java.sql.*;

public class AccountServletGood extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        resp.setContentType("text/plain");

        String user = req.getParameter("user");

        // Validate/normalize input before use (defense-in-depth)
        if (user == null || !user.matches("[A-Za-z0-9_]{1,30}")) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid user");
            return;
        }

        String sql = "SELECT balance FROM accounts WHERE user = ?"; // Use a parameterized query

        try (
            Connection conn = DriverManager.getConnection("jdbc:yourdb://host/db", "dbuser", "dbpass");
            PreparedStatement ps = conn.prepareStatement(sql);
            PrintWriter out = resp.getWriter()
        ) {
            ps.setString(1, user); // Bind untrusted input safely
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    out.println("Balance for " + user + ": " + rs.getBigDecimal(1));
                } else {
                    out.println("No account found.");
                }
            }
        } catch (SQLException e) {
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Database error");
        }
    }
}

